import * as E from './engine.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),modalContent=document.querySelector('#modal-content');
const storageSuffix=new URLSearchParams(location.search).has('playtest')?'-playtest':'';
const SAVE='don-run-v1'+storageSuffix,META='don-profile-v1'+storageSuffix,PREFS='don-prefs-v1'+storageSuffix,LOGS='don-playtests-v1'+storageSuffix;
const fmt=n=>Math.round(n).toLocaleString(),pad=n=>String(n).padStart(2,'0');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const traitInfo=mark=>E.TILE_TRAITS[mark]||null;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
let storageOK=true;
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{storageOK=false;document.querySelector('#save-status').textContent='SAVING UNAVAILABLE';}}
let meta=read(META,{runs:0,wins:0,bestRound:0,bestScore:0,discovered:[]});
if(!meta||!Array.isArray(meta.discovered))meta={runs:0,wins:0,bestRound:0,bestScore:0,discovered:[]};
let prefs=read(PREFS,{sound:true,reduced:false,volume:.72}),saved=read(SAVE,null),started=E.validSave(saved);
if(!Number.isFinite(prefs.volume))prefs.volume=.72;
let run=started?saved:E.newRun({seed:randomSeed()});
let selectedPower=null,busy=false,modalKind='',soundContext,toastTimer,slideTimer;
const isLocalPreview=['127.0.0.1','localhost'].includes(location.hostname)&&location.port==='4178';
let eventLog=read(LOGS,[]);if(!Array.isArray(eventLog))eventLog=[];
let localLoggingOK=false;
function snapshot(){return {seed:run.seed,kit:run.kit,mode:run.mode,round:run.round+1,phase:run.phase,board:[...run.board],marks:[...(run.marks??Array(16).fill(null))],score:run.score,target:E.roundInfo(run.round,run.mode).target,moves:run.moves,money:run.money,relics:[...run.relics],powers:[...run.powers],forge:run.forge,combo:run.combo,growth:run.growth,totalScore:run.totalScore,roundsCleared:run.roundsCleared,rng:run.rng,jokerRng:run.jokerRng,shopRng:run.shopRng,encoreReady:run.encoreReady,chaosRoll:run.chaosRoll,chaosFactor:run.chaosFactor,luckyTileHits:run.luckyTileHits??0,next:run.next,shop:E.clone(run.shop)};}
function logEvent(type,detail={},before=null){
  if(!started)return;
  run.logId??=crypto.randomUUID();
  const event={version:1,runId:run.logId,at:new Date().toISOString(),type,detail,before,state:snapshot()};
  eventLog.push(event);if(eventLog.length>1000)eventLog.splice(0,eventLog.length-1000);while(JSON.stringify(eventLog).length>2500000&&eventLog.length>1)eventLog.splice(0,Math.max(1,Math.floor(eventLog.length/10)));write(LOGS,eventLog);write(SAVE,run);
  if(isLocalPreview&&!storageSuffix)fetch('/api/playtest',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(event),keepalive:true}).then(r=>{localLoggingOK=r.ok;}).catch(()=>{localLoggingOK=false;});
}
function showFeedback(){showModal('feedback',`${closeButton()}<div class="eyebrow">HELP SHAPE THE NEXT RUN</div><h2 id="modal-title">How’s it feeling?</h2><p class="modal-intro">Your moves, scores, purchases and round outcomes are logged automatically. A note adds the part the numbers miss.</p><label class="feedback-label" for="feedback-kind">WHAT STOOD OUT?</label><select id="feedback-kind"><option>Something felt off</option><option>Too easy</option><option>Too hard</option><option>Confusing rule or UI</option><option>Bug</option><option>I liked this</option></select><label class="feedback-label" for="feedback-note">YOUR NOTE</label><textarea id="feedback-note" rows="4" maxlength="2000" placeholder="What happened? What did you expect?"></textarea><button class="primary wide" data-action="save-feedback">SAVE PLAYTEST NOTE <span>＋</span></button><div class="log-summary"><b>${eventLog.length.toLocaleString()} events saved on this browser</b><p>${isLocalPreview&&!storageSuffix?(localLoggingOK?'Local logs are also saved in the project, ready for Codex to read.':'Notes stay in this browser. Local log delivery will retry on your next action.'):'Download your logs to share this playtest. They contain game actions and your notes.'}</p></div><button class="secondary wide" data-action="export-logs">Download playtest logs</button>`);}
function saveFeedback(){const note=modal.querySelector('#feedback-note')?.value.trim();if(!note){toast('Add a quick note first.');return;}logEvent('feedback',{category:modal.querySelector('#feedback-kind').value,note});sound('buy');closeModal();toast('Playtest note saved with the current board.');}
function exportLogs(){const payload={game:'Double or Nothing',version:1,exportedAt:new Date().toISOString(),events:eventLog};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='double-or-nothing-playtest-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Playtest log downloaded.');}
function randomSeed(){return Math.random().toString(36).slice(2,10).toUpperCase();}
function dailySeed(){return 'DAILY-'+new Date().toISOString().slice(0,10);}
function persist(){if(started)write(SAVE,run);meta.bestRound=Math.max(meta.bestRound,run.roundsCleared);meta.bestScore=Math.max(meta.bestScore,run.totalScore);meta.discovered=[...new Set([...meta.discovered,...run.relics])];write(META,meta);}
function toast(message){clearTimeout(toastTimer);const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');toastTimer=setTimeout(()=>t.classList.remove('show'),2600);}
function sound(kind='merge',size=1){
  if(!prefs.sound)return;
  try{
    soundContext??=new (window.AudioContext||window.webkitAudioContext)();
    soundContext.resume();
    const base=kind==='win'?392:kind==='lose'?130:kind==='buy'?520:kind==='power'?330:kind==='invalid'?115:kind==='move'?180:150+Math.min(size,8)*45;
    const patterns={
      merge:[[1,0,.16,'triangle'],[1.25,.035,.12,'sine']],
      move:[[1,0,.08,'sine']],
      invalid:[[1,0,.11,'square']],
      buy:[[1,0,.12,'triangle'],[1.5,.08,.16,'sine']],
      power:[[1,0,.12,'square'],[.75,.09,.16,'triangle'],[1.5,.17,.2,'sine']],
      win:[[1,0,.18,'triangle'],[1.25,.1,.18,'triangle'],[1.5,.2,.2,'triangle'],[2,.3,.36,'sine']],
      lose:[[1,0,.22,'sawtooth'],[.72,.16,.3,'sawtooth']]
    }[kind]||[[1,0,.12,'sine']];
    const now=soundContext.currentTime;
    patterns.forEach(([ratio,offset,duration,type],i)=>{
      const osc=soundContext.createOscillator(),gain=soundContext.createGain();
      const time=now+offset,volume=Math.max(0,Math.min(1,prefs.volume))*((kind==='merge'&&i===0) ? .05 : .035);
      osc.type=type;osc.frequency.setValueAtTime(base*ratio,time);
      if(kind==='merge'&&i===0)osc.frequency.exponentialRampToValueAtTime(base*ratio*1.12,time+duration);
      gain.gain.setValueAtTime(volume,time);gain.gain.exponentialRampToValueAtTime(.001,time+duration);
      osc.connect(gain).connect(soundContext.destination);osc.start(time);osc.stop(time+duration+.02);
    });
  }catch{}
}
function updateSound(){const b=document.querySelector('#sound-button');if(!b)return;b.setAttribute('aria-pressed',String(prefs.sound));b.setAttribute('aria-label',prefs.sound?'Mute sound':'Enable sound');b.classList.toggle('enabled',prefs.sound);}
function showModal(kind,html){modalKind=kind;modalContent.innerHTML=html;if(!modal.open)modal.showModal();modal.scrollTop=0;}
function closeModal(){modal.close();modalKind='';if(!started)showMenu();else if(['danger','cleared','won','lost'].includes(run.phase))statusModal();}
const closeButton=()=>'<button class="modal-close icon-button" data-action="close" aria-label="Close dialog">×</button>';
function relicCard(id,{compact=false,shopIndex=null,sold=false}={}){
  const r=E.relic(id),fired=run.last?.triggers?.includes(id),isShop=shopIndex!==null;
  let label=sold?'SOLD':run.relics.length>=5?'SLOTS FULL':run.money<r.price?'NEED $'+r.price:'BUY · $'+r.price;
  const stateLine=id==='growth'&&run.relics.includes(id)?`<small class="growth-value">Currently ×${(1+run.growth).toFixed(2)}</small>`:id==='chaos'&&run.relics.includes(id)?`<small class="growth-value">Round blessing ×${(run.chaosFactor??1).toFixed(2)}</small>`:id==='encore'&&run.relics.includes(id)&&run.encoreReady?`<small class="growth-value">Primed for the next scoring slide</small>`:'';
  return `<article class="relic-card ${r.type} ${compact?'compact':''} ${fired?'triggered':''} ${sold?'sold':''}"><div class="card-top">${r.tag}<span>${r.icon}</span></div>${compact?'':`<div class="relic-symbol" aria-hidden="true">${r.icon}</div>`}<h3>${r.name}</h3><p>${r.desc}</p>${stateLine}<div class="card-foot"><span>${r.type.toUpperCase()}</span>${isShop?`<button class="buy-button" data-action="buy" data-index="${shopIndex}" ${sold||run.relics.length>=5||run.money<r.price?'disabled':''} aria-label="Buy ${r.name} for ${r.price} dollars">${label}</button>`:run.phase==='shop'?`<button class="sell-button" data-action="sell-confirm" data-id="${id}">Sell $${Math.floor(r.price/2)}</button>`:''}</div></article>`;
}
function powersHTML(){return `<div class="section-heading power-heading"><span>POWERUPS</span><span>${run.powers.length} / 3</span></div><div class="power-list">${run.powers.map((id,i)=>{const p=E.power(id);return `<button class="power-button ${p.target?'tile-power':''} ${selectedPower===i?'selected':''}" data-action="power" data-index="${i}" title="${esc(p.desc)}" ${run.phase==='shop'?'disabled':''} ${id==='rewind'&&!run.undo?'disabled':''} aria-label="Use ${p.name}: ${esc(p.desc)}"><span>${p.icon}</span><div><b>${p.name}<kbd>${i+1}</kbd></b><small>${p.desc}</small></div></button>`;}).join('')||'<p class="empty-copy">Pick up a little insurance in the shop.</p>'}</div>`;}
function routeHTML(){return `<div class="route"><div class="eyebrow">THE RUN</div><div class="route-dots">${Array.from({length:12},(_,i)=>{const r=E.roundInfo(i,run.mode);return `<span class="route-dot ${i<run.roundsCleared?'done':''} ${i===run.round?'current':''} ${r.boss?'boss':''}" title="Round ${i+1}: ${r.name}, ${fmt(r.target)} points" aria-label="Round ${i+1}${r.boss?' boss':''}${i===run.round?' current':''}${i<run.roundsCleared?' completed':''}">${i<run.roundsCleared?'✓':r.boss?'◆':''}</span>`;}).join('')}</div><span class="seed-label">SEED ${esc(run.seed)} · ${run.mode.toUpperCase()}</span></div>`;}
function renderGame(){const info=E.roundInfo(run.round,run.mode),title=info.boss?info.name:info.stage?'Raise the<br>stakes.':'Opening<br>hand.';
  app.innerHTML=`<section class="game-layout"><aside class="run-panel"><div class="eyebrow">ANTE ${pad(info.act)} <span class="muted">/ 04</span></div><h1>${title}</h1><p class="muted">${info.boss?info.rule.desc:run.round===0?'Make your first move.<br>Build something ridiculous.':'Fresh board. Same ambition.<br>Make your build do the work.'}</p><div class="score-panel"><span class="eyebrow">ROUND SCORE</span><strong id="score-value">${fmt(run.score)}</strong><div class="target-line">TARGET <b>${fmt(info.target)}</b></div><div class="progress" role="progressbar" aria-label="Round score" aria-valuemin="0" aria-valuemax="${info.target}" aria-valuenow="${Math.min(run.score,info.target)}"><i style="width:${Math.min(100,run.score/info.target*100)}%"></i></div></div>${E.has(run,'chaos')?`<div class="round-blessing"><span>CHAOS THEORY</span><b>ROUND ROLL ×${(run.chaosFactor??1).toFixed(2)}</b></div>`:''}<div class="stat-pair"><div><span>MOVES LEFT</span><b class="${run.moves<=6?'orange':''}">${run.moves}</b></div><div><span>YOUR CASH</span><b class="lime">$${run.money}</b></div></div>${routeHTML()}<div class="boss-preview"><span>NEXT BOSS · ${E.BOSSES[info.act-1].name}</span><p>${E.BOSSES[info.act-1].short}</p></div></aside><section class="board-area"><div class="board-heading"><span>ROUND ${pad(run.round+1)} <span class="muted">/ 12</span></span><span class="round-badge ${info.boss?'boss-badge':''}">${info.boss?'BOSS BLIND':info.stage?'BIG BLIND':'SMALL BLIND'}</span></div><div class="board ${selectedPower!==null?'targeting':''}" role="group" aria-label="2048 board. Use arrow keys or WASD to slide.">${run.board.map((v,i)=>{const merged=run.last?.merges?.some(m=>m.index===i),spawned=run.last?.spawns?.includes(i),mark=run.marks?.[i],trait=traitInfo(mark);return `<button class="cell ${!v?'empty-cell':''} ${selectedPower!==null&&v?'target-cell':''}" data-cell="${i}" aria-label="Row ${Math.floor(i/4)+1}, column ${i%4+1}: ${v||'empty'}${trait?` · ${trait.label.toLowerCase()} tile`:''}" ${selectedPower===null?'tabindex="-1"':''}>${v?`<span class="tile-face tile-${v} ${v>2048?'tile-big':''} ${merged?'tile-merge':''} ${spawned?'tile-new':''} ${trait?`tile-mark tile-${mark}`:''}">${fmt(v)}${trait?`<i class="sigil-badge sigil-${mark}" aria-hidden="true">${trait.icon}</i>`:''}</span>`:''}</button>`;}).join('')}</div><div class="board-meta"><span class="next-tile">NEXT <b class="tile-${run.next}">${run.next}</b></span><span class="streak-label ${run.combo>=2?'active':''}">${run.combo>=2?'✦ '+run.combo+' SLIDE STREAK':'MERGE TO BUILD A STREAK'}</span>${run.focus?`<span class="focus-label">×2 · ${run.focus} left</span>`:''}</div>${selectedPower!==null?`<div class="target-hint">${E.power(run.powers[selectedPower]).name}: choose a tile <button data-action="cancel-power">Cancel</button></div>`:`<div class="controls-hint">← ↑ ↓ → <span>or WASD to slide · swipe on mobile</span></div>`}<div class="direction-pad" aria-label="Slide controls">${[['left','←'],['up','↑'],['down','↓'],['right','→']].map(([d,a])=>`<button data-action="move" data-dir="${d}" aria-label="Slide ${d}">${a}</button>`).join('')}</div><button class="score-readout" data-action="breakdown" aria-label="Show last slide score breakdown"><span>LAST SLIDE</span>${run.last?.points?`<span class="score-equation">${fmt(run.last.chips)} <span>× ${run.last.mult.toFixed(2)}</span></span><b>+${fmt(run.last.points)}</b>`:`<b>${run.last?'Set up the next merge.':'Your move.'}</b>`}</button><div class="round-footnote">${run.forge?`WORKSHOP ×${(1+run.forge*.2).toFixed(1)} · `:''}Base streak: +0.15× per step, up to +0.75×</div></section><aside class="build-panel"><div class="section-heading"><span>YOUR JOKERS</span><span>${run.relics.length} / 5</span></div><div class="relic-inventory ${run.relics.length>1?'stacked':''}">${run.relics.map(id=>relicCard(id,{compact:run.relics.length>1})).join('')}</div>${run.relics.length<5?`<div class="empty-relic">+<span>${5-run.relics.length} open slot${run.relics.length===4?'':'s'}. Find your combo.</span></div>`:''}${powersHTML()}</aside></section>`;
}
function renderShop(){const next=E.roundInfo(run.round+1,run.mode);app.innerHTML=`<section class="shop-layout"><div class="shop-header"><div><div class="eyebrow">A MOMENT BETWEEN ROUNDS</div><h1>The night market.</h1><p class="muted">Buy a spark. Find a combo. Know when to walk away.</p></div><div class="wallet"><span>YOUR CASH</span><b>$${run.money}</b><small>$1 interest per $5 saved · max $3</small></div></div><div class="shop-section-title"><h2>Something for your build</h2><button class="secondary" data-action="reroll" ${run.money<E.rerollPrice(run)?'disabled':''}>↻ Reroll · $${E.rerollPrice(run)}</button></div><div class="shop-relics">${run.shop.filter(i=>i.kind==='relic').map(i=>relicCard(i.id,{shopIndex:run.shop.indexOf(i),sold:i.sold})).join('')}</div><div class="shop-bottom"><section><div class="section-heading"><span>TILE & POWERUPS</span><span>POWERUPS ${run.powers.length} / 3</span></div><div class="shop-powers">${run.shop.filter(i=>i.kind==='power').map(item=>{const p=E.power(item.id),blocked=item.sold||run.powers.length>=3||run.money<p.price;return `<article class="shop-power ${p.target?'tile-power':''} ${item.sold?'sold':''}"><span class="power-symbol">${p.icon}</span><div><h3>${p.name}</h3><p>${p.desc}</p></div><button class="buy-button" data-action="buy" data-index="${run.shop.indexOf(item)}" ${blocked?'disabled':''}>${item.sold?'SOLD':run.powers.length>=3?'FULL':'$'+p.price}</button></article>`;}).join('')}</div></section><section class="workshop"><div class="eyebrow">THE WORKSHOP</div><h3>A sure thing.</h3><p>Upgrade every scoring slide. <b>×${(1+run.forge*.2).toFixed(1)} → ×${(1+(run.forge+1)*.2).toFixed(1)}</b></p><button class="secondary" data-action="forge" ${run.money<E.forgePrice(run)||run.forge>=6?'disabled':''}>${run.forge>=6?'MAX LEVEL':`Upgrade · $${E.forgePrice(run)}`}</button></section></div><details class="shop-inventory" ${run.relics.length>=5?'open':''}><summary>Your build · ${run.relics.length} / 5 jokers <span>Manage & sell</span></summary><div class="shop-owned">${run.relics.map(id=>relicCard(id,{compact:true})).join('')||'<p>No jokers. Bold choice.</p>'}</div><div class="stored-powers">${run.powers.map((id,i)=>`<span>${E.power(id).icon} ${E.power(id).name} <button data-action="discard-confirm" data-index="${i}" aria-label="Discard ${E.power(id).name}">×</button></span>`).join('')}</div></details><div class="leave-shop"><div><span class="eyebrow">UP NEXT · ROUND ${pad(run.round+2)}</span><h3>${next.name} <span class="muted">/ ${fmt(next.target)} points</span></h3><p>${next.boss?next.rule.desc:`${next.moves+(E.has(run,'clock')?4:0)} moves · Fresh board · Your build carries over`}</p></div><button class="primary" data-action="next">LET’S PLAY <span>→</span></button></div></section>`;}
function render(){updateSound();if(run.phase==='shop')renderShop();else renderGame();}
function showMenu(){selectedPower=null;const resumable=started&&!['won','lost'].includes(run.phase);showModal('menu',`${resumable?closeButton():''}<div class="eyebrow">2048. WITH A FEW NEW RULES.</div><h2 id="modal-title" class="menu-title">Double<br>or nothing<span class="lime">.</span></h2><p class="modal-intro">Merge tiles. Stack jokers. Beat the house.<br>12 rounds. 4 bosses. One very good combo.</p>${resumable?`<button class="primary wide" data-action="resume">RESUME · ROUND ${run.round+1}<span>→</span></button><div class="menu-divider">OR DEAL A NEW RUN</div>`:''}<fieldset class="kit-picker"><legend>CHOOSE YOUR STARTING KIT</legend>${E.KITS.map((k,i)=>{const locked=meta.bestRound<k.unlock;return `<label class="kit-option ${locked?'locked':''}"><input type="radio" name="kit" value="${k.id}" ${i===0?'checked':''} ${locked?'disabled':''}><span class="kit-symbol">${k.icon}</span><span><b>${k.name}</b><small>${locked?`Clear ${k.unlock} rounds in one run to unlock.`:k.desc}</small></span>${locked?'<span>⌑</span>':''}</label>`;}).join('')}</fieldset><div class="run-options"><label>STAKES<select id="difficulty"><option value="standard">Standard</option><option value="relaxed">Easygoing · more room</option><option value="expert" ${meta.wins?'':'disabled'}>High stakes${meta.wins?'':' · win to unlock'}</option></select></label><label>SEED <span>OPTIONAL</span><input id="seed-input" maxlength="40" placeholder="Leave it to luck" autocomplete="off" spellcheck="false"></label></div><button class="primary wide" data-action="start">${resumable?'REPLACE RUN & DEAL':'DEAL ME IN'} <span>→</span></button><button class="text-button daily-button" data-action="daily">Play today’s fixed seed · UTC</button><div class="menu-stats"><span><b>${meta.runs}</b> RUNS</span><span><b>${meta.wins}</b> WINS</span><span><b>${meta.discovered.length} / ${E.RELICS.length}</b> JOKERS FOUND</span></div>`);}
function startGame(daily=false){const kit=modal.querySelector('input[name="kit"]:checked')?.value||'spark',mode=daily?'standard':modal.querySelector('#difficulty')?.value||'standard',seed=daily?dailySeed():modal.querySelector('#seed-input')?.value.trim()||randomSeed();run=E.newRun({seed,kit:daily?'spark':kit,mode});started=true;meta.runs++;selectedPower=null;modal.close();modalKind='';persist();render();sound('power');toast('Reach the target before your moves run out.');}
function statusModal(){
  if(run.phase==='cleared'){const p=run.receipt,next=E.roundInfo(run.round+1,run.mode);showModal('cleared',`<div class="win-glyph">✦</div><div class="eyebrow">ROUND ${pad(run.round+1)} CLEARED</div><h2 id="modal-title">Beautifully played.</h2><p class="modal-intro">${fmt(run.score)} points. ${run.moves} moves to spare.</p><div class="receipt"><div>Blind reward<b>$${p.base}</b></div><div>Moves saved <small>$1 per 5 · max $3</small><b>$${p.speed}</b></div><div>Interest <small>$1 per $5 · max $3</small><b>$${p.interest}</b></div>${p.bank?`<div>Rainy Day<b>$${p.bank}</b></div>`:''}${p.lucky!==undefined?`<div>Lucky Break <small>roll ${p.luckyRoll}</small><b>$${p.lucky}</b></div>`:''}<div class="receipt-total">TAKE HOME<b>+$${p.total}</b></div></div>${[3,6,9].includes(run.roundsCleared)?`<div class="unlock-notice">✧ New starting kit unlocked: ${run.roundsCleared===3?'The Banker':run.roundsCleared===6?'The Architect':'The High Roller'}</div>`:''}<button class="primary wide" data-action="shop">VISIT THE SHOP <span>→</span></button><p class="dialog-footnote">Next: ${next.name} · ${fmt(next.target)} points</p><button class="text-button daily-button" data-action="feedback">Add playtest note</button>`);}
  if(run.phase==='danger'){const movesGone=run.moves<=0;showModal('danger',`<div class="eyebrow">ONE LAST CHANCE?</div><h2 id="modal-title">${movesGone?'Out of moves.':'Nowhere to slide.'}</h2><p class="modal-intro">${fmt(run.score)} / ${fmt(E.roundInfo(run.round,run.mode).target)} points. ${run.powers.length?'A powerup might keep this run alive.':'Sometimes the house wins. Your next build awaits.'}</p><div class="rescue-powers">${run.powers.map((id,i)=>{const p=E.power(id),useful=movesGone?['moves','rewind'].includes(id):['hammer','shuffle','promote','rewind'].includes(id);return useful?`<button class="secondary" data-action="rescue" data-index="${i}" ${id==='rewind'&&!run.undo?'disabled':''}>${p.icon} ${p.name}</button>`:'';}).join('')}</div><button class="primary wide danger-primary" data-action="end">END THIS RUN <span>→</span></button>`);}
  if(['won','lost'].includes(run.phase)){if(!run.recorded){run.recorded=true;if(run.phase==='won')meta.wins++;persist();}showModal('end',`<div class="win-glyph">${run.phase==='won'?'♜':'◇'}</div><div class="eyebrow">${run.phase==='won'?'THE HOUSE IS YOURS':'THE END OF THIS HAND'}</div><h2 id="modal-title">${run.phase==='won'?'You broke the house.':'Another run, another idea.'}</h2><p class="modal-intro">${run.phase==='won'?'Twelve rounds down. One ridiculous little engine.':'Every run is a new puzzle. Keep the knowledge; try a new combo.'}</p><div class="end-stats"><div><b>${run.roundsCleared} / 12</b><span>ROUNDS CLEARED</span></div><div><b>${fmt(run.totalScore)}</b><span>TOTAL SCORE</span></div><div><b>${fmt(run.highest)}</b><span>HIGHEST TILE</span></div><div><b>${run.totalMerges}</b><span>MERGES</span></div></div><div class="final-build">${run.relics.map(id=>`<span title="${esc(E.relic(id).desc)}">${E.relic(id).icon} ${E.relic(id).name}</span>`).join('')}</div>${run.phase==='won'?'<div class="unlock-notice">High stakes unlocked. The targets just got bigger.</div>':''}<button class="primary wide" data-action="menu">ONE MORE RUN <span>↻</span></button><button class="secondary wide replay-button" data-action="replay">Replay seed ${esc(run.seed)}</button>`);}
}
function moveBoard(dir){if(busy||modal.open||selectedPower!==null||!started)return false;const before=snapshot();if(!E.move(run,dir)){const b=document.querySelector('.board');b?.animate([{transform:'translateX(0)'},{transform:'translateX(-4px)'},{transform:'translateX(4px)'},{transform:'translateX(0)'}],{duration:160,easing:'ease-out'});sound('invalid');return false;}persist();logEvent('move',{direction:dir,scoring:run.last,receipt:run.receipt},before);render();animateSlide();sound(run.last.merges.length?'merge':'move',Math.log2(Math.max(...run.last.merges.map(m=>m.value),2)));document.querySelector('#announcement').textContent=`${run.last.points?`Plus ${run.last.points} points. `:''}Score ${run.score} of ${E.roundInfo(run.round,run.mode).target}. ${run.moves} moves left.`;return true;}
function animateSlide(){
  const board=document.querySelector('.board');if(!board||!run.last)return;
  busy=true;const reduced=prefs.reduced||matchMedia('(prefers-reduced-motion: reduce)').matches,duration=reduced?0:150;
  const cells=[...board.querySelectorAll('.cell')],box=board.getBoundingClientRect();
  if(!reduced){
    board.classList.add('is-sliding');
    for(const m of run.last.motions){
      const from=cells[m.from].getBoundingClientRect(),to=cells[m.to].getBoundingClientRect(),ghost=document.createElement('span');
      ghost.className=`moving-tile tile-${m.value} ${m.value>2048?'tile-big':''}`;ghost.textContent=fmt(m.value);
      Object.assign(ghost.style,{left:(from.left-box.left-1)+'px',top:(from.top-box.top-1)+'px',width:from.width+'px',height:from.height+'px'});board.append(ghost);
      ghost.animate([{transform:'translate(0,0)'},{transform:`translate(${to.left-from.left}px,${to.top-from.top}px)`}],{duration,fill:'forwards',easing:'cubic-bezier(.2,.7,.2,1)'});
    }
    const score=document.createElement('div');score.className='score-floater';score.textContent=run.last.points?`+${fmt(run.last.points)}`:'SLIDE';
    score.style.left='50%';score.style.top='42%';board.append(score);score.animate([{opacity:0,transform:'translate(-50%,12px) scale(.8)'},{opacity:1,transform:'translate(-50%,0) scale(1)'},{opacity:0,transform:'translate(-50%,-32px) scale(1.06)'}],{duration:560,easing:'cubic-bezier(.2,.8,.2,1)'});
    run.last.merges.forEach((m,index)=>{
      const cell=cells[m.index],rect=cell.getBoundingClientRect(),burst=document.createElement('div');burst.className='merge-burst';
      burst.style.left=`${rect.left-box.left+rect.width/2}px`;burst.style.top=`${rect.top-box.top+rect.height/2}px`;
      burst.innerHTML=Array.from({length:6},(_,i)=>`<i style="--angle:${i*60}deg;--delay:${i*.025}s"></i>`).join('');board.append(burst);
      burst.animate([{opacity:1,transform:'translate(-50%,-50%) scale(.4)'},{opacity:1,transform:`translate(-50%,-50%) scale(${1+Math.min(m.value/512,.8)})`},{opacity:0,transform:'translate(-50%,-50%) scale(1.35)'}],{duration:420,delay:index*20,easing:'cubic-bezier(.15,.8,.2,1)'});
    });
    document.querySelector('.score-panel')?.animate([{transform:'scale(1)'},{transform:'scale(1.025)'},{transform:'scale(1)'}],{duration:260,easing:'ease-out'});
  }
  clearTimeout(slideTimer);slideTimer=setTimeout(()=>{
    board.classList.remove('is-sliding');board.querySelectorAll('.moving-tile,.score-floater,.merge-burst').forEach(e=>e.remove());
    if(!reduced)run.last?.merges.forEach(m=>cells[m.index]?.querySelector('.tile-face')?.animate([{transform:'scale(.9)'},{transform:'scale(1.16)'},{transform:'scale(1)'}],{duration:220,easing:'cubic-bezier(.2,.8,.2,1)'}));
    busy=false;if(run.phase!=='playing'){if(['cleared','won'].includes(run.phase))sound('win');else if(run.phase==='danger')sound('lose');statusModal();}
  },duration+25);
}
function targetHint(id){return ({promote:'Choose a tile worth 256 or less.',engrave:'Choose an unmarked tile to foil stamp.',multstamp:'Choose an unmarked tile for Mult Ink.',luckyseal:'Choose an unmarked tile for a Lucky Seal.',glasscut:'Choose an unmarked tile for Glass Cut.',hammer:'Choose a tile to remove.'}[id])||'Choose a tile.';}
function activatePower(index){if(busy||!['playing','danger'].includes(run.phase))return;const before=snapshot();const p=E.power(run.powers[index]);if(!p)return;if(p.target){selectedPower=selectedPower===index?null:index;modal.close();modalKind='';render();if(selectedPower!==null)toast(targetHint(p.id));}else if(E.usePower(run,index)){logEvent('use_power',{power:p.id},before);selectedPower=null;modal.close();modalKind='';sound('power');persist();render();statusModal();toast(p.name+' used.');}else toast('That powerup cannot be used right now.');}
function help(){showModal('help',`${closeButton()}<div class="eyebrow">THE HOUSE RULES</div><h2 id="modal-title">A familiar game.<br>A different kind of run.</h2><div class="help-grid"><article><span>01</span><h3>Slide & merge</h3><p>Use arrows, WASD, on-screen buttons, or swipe. Equal tiles merge once per slide: 2 + 2 = 4. Each successful slide costs one move and spawns a tile. A direction that changes nothing is free.</p></article><article><span>02</span><h3>Beat the target</h3><p>Merged values become chips. Jokers and marked tiles add chips, multipliers, cash, and strange conditions. Your final score is <b>chips × multiplier</b>, rounded once. You do not need a 2048 tile to win.</p></article><article><span>03</span><h3>Build a combo</h3><p>Carry up to 5 jokers and 3 powerups. Jokers last the whole run; powerups are used once. Consecutive scoring slides add +0.15× per step, capped at +0.75×. A slide with no merge breaks the streak.</p></article><article><span>04</span><h3>Spend with a plan</h3><p>Earn cash after every round. Save $5 to earn $1 interest, up to $3. Buy jokers, reroll, or take a guaranteed workshop upgrade. Sell jokers in the shop when you need a slot.</p></article></div><div class="help-note"><b>12 rounds · 4 bosses · no timer.</b> Every round starts with a fresh board and larger starting tiles each ante. Boss rules are shown in advance. Powerups cost no moves; Double Up gives no points. Foil, Mult, Lucky, and Glass upgrades attach to occupied tiles and move through merges. Glass pays ×2.5 once and shatters; Lucky can pay $3 and +0.60×; Mult adds +0.45× whenever it merges. Rewind restores the last slide and its randomness, and cannot undo another powerup. Alternate kits unlock after clearing rounds 3, 6, and 9. Saves and unlocks stay on this browser.</div><button class="primary wide" data-action="close">GOT IT <span>→</span></button>`);}
function notes(){showModal('notes',`${closeButton()}<div class="eyebrow">BEHIND THE RULES</div><h2 id="modal-title">Designed around decisions.</h2><div class="notes-copy"><p><b>Familiar at the center.</b> LocalThunk describes Balatro’s roots in the comfortable, repeatable ritual of solitaire. Here, standard 2048 movement stays intact while a run supplies new goals. <a href="https://localthunk.com/blog/solitaire" target="_blank" rel="noopener noreferrer">Read LocalThunk’s essay ↗</a></p><p><b>Combinations over isolated buffs.</b> Mega Crit’s designers describe rewarding synergies and enemies that test different strategies. Five joker slots, conditional bonuses, and visible boss rules create those tradeoffs. <a href="https://www.gamedeveloper.com/game-platforms/road-to-the-igf-mega-crit-games-i-slay-the-spire-i-" target="_blank" rel="noopener noreferrer">Read the designer interview ↗</a></p><p><b>Test, then keep listening.</b> Mega Crit’s balance talk pairs metrics with playtesting. This game’s targets were checked with automated runs using several play policies. Those simulations test the curve, not how enjoyable it feels to a person. <a href="https://media.gdcvault.com/gdc2019/presentations/Giovannetti_Anthony_SlayTheSpire.pdf" target="_blank" rel="noopener noreferrer">View the GDC talk slides ↗</a></p><p><b>No permanent stat grind.</b> Unlocks open alternate starting kits and higher stakes. Cash, jokers, and score reset for each run. Daily runs use the same UTC seed, kit, and stakes for everyone, with no online leaderboard.</p></div>`);}
function pause(){if(!started){showMenu();return;}if(busy)return;showModal('pause',`${closeButton()}<div class="eyebrow">TAKE YOUR TIME</div><h2 id="modal-title">The table can wait.</h2><p class="modal-intro">${storageOK?'Your run is saved on this browser.':'Browser storage is unavailable. Keep this tab open to preserve your run.'}</p><button class="primary wide" data-action="resume">BACK TO THE TABLE <span>→</span></button><button class="secondary wide replay-button" data-action="help">How to play</button><button class="secondary wide replay-button" data-action="menu">New run & starting kits</button><label class="motion-toggle"><input id="motion-toggle" type="checkbox" ${prefs.reduced?'checked':''}> Reduce animation</label><label class="volume-control" for="volume-toggle"><span>SOUND VOLUME</span><output id="volume-output">${Math.round((prefs.volume??.72)*100)}%</output><input id="volume-toggle" type="range" min="0" max="1" step=".05" value="${prefs.volume??.72}"></label><p class="dialog-footnote">Seed ${esc(run.seed)} · ${run.mode}</p>`);}
function breakdown(){const l=run.last;if(!l?.points){toast('Make a merge to see how your score adds up.');return;}showModal('breakdown',`${closeButton()}<div class="eyebrow">EVERY POINT, ACCOUNTED FOR</div><h2 id="modal-title">${fmt(l.chips)} <span class="muted">×</span> ${l.mult.toFixed(2)}</h2><p class="breakdown-total">+${fmt(l.points)} points</p><div class="receipt">${l.lines.map(x=>`<div>${x.label}<b>${typeof x.value==='number'?'+'+fmt(x.value):x.value}</b></div>`).join('')}<div>Base streak multiplier<b>×${(1+Math.min(Math.max(0,run.combo-1),5)*.15).toFixed(2)}</b></div></div><p class="dialog-footnote">Add all chips. Combine the streak and Echo bonus, then multiply other bonuses. Round the final result once.</p>`);}
function handleAction(action,button){const before=started?snapshot():null;const i=Number(button?.dataset.index);switch(action){
  case 'feedback':showFeedback();break;case 'save-feedback':saveFeedback();break;case 'export-logs':exportLogs();break;
  case 'start':startGame();break;case 'daily':startGame(true);break;case 'close':closeModal();break;case 'help':help();break;case 'notes':notes();break;case 'pause':pause();break;case 'menu':showMenu();break;
  case 'resume':modal.close();modalKind='';render();statusModal();break;
  case 'replay':{const {seed,kit,mode}=run;run=E.newRun({seed,kit,mode});meta.runs++;started=true;modal.close();modalKind='';persist();render();break;}
  case 'sound':prefs.sound=!prefs.sound;write(PREFS,prefs);updateSound();sound('buy');toast(prefs.sound?'Sound on.':'Sound off.');break;
  case 'move':moveBoard(button.dataset.dir);break;case 'breakdown':breakdown();break;
  case 'shop':if(E.enterShop(run)){modal.close();modalKind='';persist();render();}break;
  case 'next':if(E.nextRound(run)){persist();render();sound('power');window.scrollTo({top:0,behavior:'instant'});}break;
  case 'buy':if(E.buy(run,i)){persist();render();sound('buy');toast('Added to your build.');}break;
  case 'reroll':if(E.reroll(run)){persist();render();sound('buy');}break;
  case 'forge':if(E.forge(run)){persist();render();sound('buy');toast(`Workshop upgraded to ×${(1+run.forge*.2).toFixed(1)}.`);}break;
  case 'sell-confirm':{const r=E.relic(button.dataset.id);showModal('sell',`${closeButton()}<div class="eyebrow">MAKE ROOM FOR SOMETHING NEW</div><h2 id="modal-title">Sell ${r.name}?</h2><p class="modal-intro">Receive $${Math.floor(r.price/2)} and free one joker slot. Its effect leaves your build.</p><button class="primary wide" data-action="sell" data-id="${r.id}">SELL FOR $${Math.floor(r.price/2)}</button>`);break;}
  case 'sell':if(E.sell(run,button.dataset.id)){modal.close();modalKind='';persist();render();sound('buy');}break;
  case 'discard-confirm':{const p=E.power(run.powers[i]);showModal('discard',`${closeButton()}<h2 id="modal-title">Discard ${p.name}?</h2><p class="modal-intro">Free one powerup slot. Discarded powerups do not give cash.</p><button class="primary wide" data-action="discard" data-index="${i}">DISCARD</button>`);break;}
  case 'discard':if(E.discardPower(run,i)){modal.close();modalKind='';persist();render();}break;
  case 'power':case 'rescue':activatePower(i);break;
  case 'cancel-power':selectedPower=null;render();statusModal();break;
  case 'end':E.finish(run);persist();render();statusModal();break;
}if(['start','daily','replay','shop','next','buy','reroll','forge','sell','discard','end'].includes(action))logEvent(action,{index:Number.isFinite(i)?i:null,id:button?.dataset.id||null},before);}
document.addEventListener('click',event=>{const cell=event.target.closest('[data-cell]');if(cell&&selectedPower!==null){const before=snapshot();const p=E.power(run.powers[selectedPower]);if(E.usePower(run,selectedPower,Number(cell.dataset.cell))){logEvent('use_power',{power:p.id,target:Number(cell.dataset.cell)},before);selectedPower=null;sound('power');persist();render();statusModal();}else toast(targetHint(p.id));return;}const button=event.target.closest('[data-action]');if(button&&!button.disabled)handleAction(button.dataset.action,button);});
document.addEventListener('input',e=>{if(e.target.id==='volume-toggle'){prefs.volume=Number(e.target.value);const output=document.querySelector('#volume-output');if(output){output.value=`${Math.round(prefs.volume*100)}%`;output.textContent=output.value;}write(PREFS,prefs);}});
document.addEventListener('change',e=>{if(e.target.id==='motion-toggle'){prefs.reduced=e.target.checked;write(PREFS,prefs);}if(e.target.id==='volume-toggle'){sound('buy');}});
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey)return;if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(e.key==='Escape'){if(selectedPower!==null){e.preventDefault();selectedPower=null;render();statusModal();}else if(!modal.open){e.preventDefault();pause();}return;}if(modal.open)return;if(e.repeat)return;const d={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down',a:'left',d:'right',w:'up',s:'down'}[e.key]||{a:'left',d:'right',w:'up',s:'down'}[e.key.toLowerCase()];if(d){e.preventDefault();moveBoard(d);}else if(['1','2','3'].includes(e.key))activatePower(Number(e.key)-1);else if(e.key==='?')help();else if(e.key.toLowerCase()==='f')showFeedback();});
modal.addEventListener('cancel',e=>{e.preventDefault();if(!['cleared','danger','end'].includes(modalKind))closeModal();});
let pointerStart=null;
document.addEventListener('pointerdown',e=>{if(e.target.closest('.board')&&selectedPower===null&&!modal.open){pointerStart={x:e.clientX,y:e.clientY,id:e.pointerId};e.target.setPointerCapture?.(e.pointerId);}});
document.addEventListener('pointerup',e=>{if(!pointerStart||e.pointerId!==pointerStart.id)return;const dx=e.clientX-pointerStart.x,dy=e.clientY-pointerStart.y;pointerStart=null;if(Math.max(Math.abs(dx),Math.abs(dy))>25)moveBoard(Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up');});
document.addEventListener('pointercancel',()=>pointerStart=null);
// A second open copy yields when another tab saves, avoiding silent save clobbering.
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&started)persist();});
window.addEventListener('storage',event=>{if(event.key===SAVE&&event.newValue){try{const external=JSON.parse(event.newValue);if(E.validSave(external)){run=external;started=true;selectedPower=null;render();pause();toast('Run updated in another tab.');}}catch{}}});
// Progressive WebMCP support, where implemented by the browser. State is device-local.
const modelContext=document.modelContext || navigator.modelContext;
if(modelContext?.registerTool){
  const lifecycle=new AbortController();
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
  const register=tool=>{try{Promise.resolve(modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
  const output=value=>({content:[{type:'text',text:JSON.stringify(value)}]});
  register({name:'get_game_state',annotations:{readOnlyHint:true,untrustedContentHint:false},description:'Read the current 2048 roguelite board, score, target, moves, jokers, tile marks, powerups and shop. No changes.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:async()=>output({phase:run.phase,board:run.board,marks:run.marks??Array(16).fill(null),round:run.round+1,info:E.roundInfo(run.round,run.mode),score:run.score,moves:run.moves,money:run.money,luckyTileHits:run.luckyTileHits??0,relics:run.relics.map(E.relic),powers:run.powers.map(E.power),shop:run.shop,dialog:modalKind})});
  register({name:'slide_tiles',annotations:{readOnlyHint:false,untrustedContentHint:false},description:'Slide the live 2048 board in one direction. Costs one move if the board changes. Only works during active play with no dialog open.',inputSchema:{type:'object',properties:{direction:{type:'string',enum:E.DIRS}},required:['direction'],additionalProperties:false},execute:async(input)=>{if(!input||!E.DIRS.includes(input.direction))return output({error:'Direction must be left, up, right, or down.'});const moved=moveBoard(input.direction);if(moved)await new Promise(resolve=>setTimeout(resolve,165));return output({moved,score:run.score,moves:run.moves,phase:run.phase});}});
}
render();if(!started)showMenu();else{logEvent('resume');statusModal();}
